CREATE TABLE customer (c_custkey Int32, c_name String, c_nationkey Int32, c_mktsegment LowCardinality(String), c_acctbal Decimal(12, 2)) ENGINE = MergeTree ORDER BY c_custkey;
CREATE TABLE orders (o_orderkey Int32, o_custkey Int32, o_orderstatus LowCardinality(String), o_totalprice Decimal(12, 2), o_orderdate Date, o_orderpriority LowCardinality(String), o_shippriority Int32) ENGINE = MergeTree ORDER BY o_orderkey;
CREATE TABLE lineitem (l_orderkey Int32, l_linenumber Int32, l_quantity Decimal(12, 2), l_extendedprice Decimal(12, 2), l_discount Decimal(12, 2), l_tax Decimal(12, 2), l_shipdate Date, l_commitdate Date, l_receiptdate Date, l_returnflag LowCardinality(String), l_linestatus LowCardinality(String), l_shipmode LowCardinality(String), l_shipinstruct LowCardinality(String)) ENGINE = MergeTree ORDER BY (l_shipdate, l_orderkey)
